const src = $json;

function pick(...vals){for(const v of vals){if(v!==undefined&&v!==null&&v!=='')return v;}return ''}

const title = pick(src?.status?.title, src?.response?.title, 'Titan Alert');
const severity = pick(src?.status?.severity, src?.response?.severity, 'unknown');
const category = pick(src?.status?.category, src?.response?.category, 'unknown');

const message = pick(src?.response?.message);
const explanation = pick(src?.response?.explanation);
const suggestedFix = pick(src?.response?.suggested_fix);

const provider = pick(src?.telemetry?.signature?.provider, 'unknown');
const errorType = pick(src?.telemetry?.signature?.error_type, 'unknown');

const manualReview = src?.decision?.manual_review_required === true;

let color = '#2E7D32';
let header = '🟢 TITAN OK';

if (severity === 'error') {
  color = '#D32F2F';
  header = '🔴 TITAN ERROR';
} else if (severity === 'warning') {
  color = '#F9A825';
  header = '🟠 TITAN WARNING';
}

if (manualReview) {
  color = '#D32F2F';
  header = '🚨 MANUAL REVIEW REQUIRED';
}

const blocks = [];

blocks.push({
  type: 'header',
  text: { type: 'plain_text', text: header }
});

blocks.push({
  type: 'section',
  text: {
    type: 'mrkdwn',
    text: `*${title}*\n*Severity:* \`${severity}\`    *Category:* \`${category}\``
  }
});

if (message) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `*Message*\n${message}` }
  });
}

if (explanation) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `*Explanation*\n${explanation}` }
  });
}

if (suggestedFix) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `*Suggested Fix*\n${suggestedFix}` }
  });
}

blocks.push({ type: 'divider' });

blocks.push({
  type: 'context',
  elements: [
    { type: 'mrkdwn', text: `*provider:* ${provider}` },
    { type: 'mrkdwn', text: `*error type:* ${errorType}` }
  ]
});

return [
  {
    json: {
      slack_blocks: blocks,
      slack_color: color,
      slack_text: `${header} - ${title}`
    }
  }
];
